validator:
function validate(input) {
  const [{ Activities = [] }] = input;
  for (const [date, product] of Activities) {
    if (date === null || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return 'Every sell_date must be a date like 2020-05-30.';
    if (product === null || product === '' || product.includes(',')) return 'Every product needs a name without commas.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const Activities = [];
  if (size === 'small') {
    const dates = ['2020-05-30', '2020-06-01', '2020-06-02', '2019-12-31'];
    const products = ['Headphone', 'Pencil', 'Pen', 'Mask', 'Basketball', 'Bible', 'T-Shirt', 'Lamp'];
    const rows = Math.floor(rand() * 9);
    for (let i = 0; i < rows; i++) {
      // Repeat the previous row now and then so duplicates are common.
      if (Activities.length && rand() < 0.25) Activities.push([...Activities[Activities.length - 1]]);
      else Activities.push([pick(dates), pick(products)]);
    }
  } else {
    const letters = 'abcdefghijklmnopqrstuvwxyz';
    const products = Array.from({ length: 60 }, (_, i) => `Item${letters[i % 26]}${letters[Math.floor(i / 26)]}`);
    for (let i = 0; i < 2000; i++) {
      const day = new Date(Date.UTC(2020, 0, 1 + Math.floor(rand() * 200))).toISOString().slice(0, 10);
      Activities.push([day, pick(products)]);
    }
  }
  return [{ Activities }];
}
